#include <stdint.h>

#include <stdio.h>

#include "stm32f446xx.h"



#if !defined(__SOFT_FP__) && defined(__ARM_FP)

  #warning __"FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."__

#endif



void uart_write(int ch){

        while(!(USART2->SR & (1U << 7))){}

        USART2->DR = (ch & 0xFF);
    }

int uart_read(){

        while(!(USART2->SR & (1U << 5))){}
        uint8_t ch = USART2->DR;
        if(ch == '\r'){
        	ch = '\n';
        }
        return ch;
    }


//printf calls this

int __io_putchar(int ch) {

    uart_write(ch);
    return ch;
}

void myScanf(int max, char* message){


	int l = 0;

	while(l <= max - 1){
		uint8_t ch = uart_read();
		if(ch == '\n' || ch == '\r'){
			uart_write('\n');
			uart_write('\r');
			break;
		}
		message[l] = ch;
		uart_write(ch);
		l++;
	}

	message[l] = '\0';

	/* custom printf
	for(int i = 0; i < l; i++){
		uart_write(message[i]);
	}
	uart_write('\n');
	uart_write('\r');
	*/
}



int main(void)
{

    RCC->AHB1ENR |= (1U << 0); //enable port for gpioa
    RCC->APB1ENR |= (1U << 17); //enable port for usart2
    GPIOA->MODER &= ~(1U << 4); //set alt func for pa2
    GPIOA->MODER |= (1U << 5);  //find pa2 for tx in datasheet
    GPIOA->MODER &= ~(1U << 6); //set alt func for pa3
    GPIOA->MODER |= (1U << 7); ////find pa3 for rx in datasheet
    GPIOA->AFR[0] |= (1U << 10) | (1U << 9) | (1U << 8) | (1U << 14) | (1U << 13) | (1U << 12); //find af7 = usart2 in datasheet and select pa2 and pa3 alt funcs
    USART2->BRR = 16000000/115200; //clkspd/baud rate
    USART2->CR1 = 0; //clear cr1 register
    USART2->CR1 |= (1U << 2) | (1U << 3); //enable reciever and transmitter
    USART2->CR1 |= (1U << 13); //start usart2

    char message[40];

    while(1) {
        myScanf(40, message);
        printf("%s\r\n", message);
    }
}

